BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=extensions,pg_catalog,public;
SELECT plan(31);
SELECT is(app_private.db03_render_admission_number('CHAR','-','FULL_YEAR','2026-08-01',4,1,1),'CHAR-2026-0001','full-year 4-digit serial');
SELECT is(app_private.db03_render_admission_number('CHAR','-','TWO_DIGIT_YEAR','2026-08-01',4,1,1),'CHAR-26-0001','two-digit session year');
SELECT is(app_private.db03_render_admission_number('','-','FULL_YEAR','2026-08-01',4,1,9),'2026-0009','empty optional prefix has no leading separator');
SELECT is(app_private.db03_render_admission_number('CHAR','','FULL_YEAR','2026-08-01',4,1,9),'CHAR20260009','empty optional separator remains deterministic');
SELECT is(app_private.db03_render_admission_number('C','/','FULL_YEAR','2026-08-01',1,1,9),'C/2026/9','single-digit width boundary');
SELECT is(app_private.db03_render_admission_number('C','_','FULL_YEAR','2026-08-01',8,1,1),'C_2026_00000001','8-digit serial zero padding');
SELECT is(app_private.db03_render_admission_number('C','-','FULL_YEAR','2026-08-01',4,1,9999),'C-2026-9999','highest serial for four-digit format');
SELECT is(app_private.db03_render_admission_number('C','-','TWO_DIGIT_YEAR','2000-01-01',4,1,99),'C-00-0099','year 2000 maps to 00 in two-digit format');
SELECT is(app_private.db03_render_admission_number('C','-','TWO_DIGIT_YEAR','1999-01-01',4,1,99),'C-99-0099','year 1999 maps to 99');
SELECT is(app_private.db03_render_admission_number('مدرسة','-','FULL_YEAR','2026-01-01',4,1,1),'مدرسة-2026-0001','non-English prefix remains supported');
SELECT ok(to_regprocedure('app_private.db03_render_admission_number(text,text,text,date,integer,bigint,bigint)') IS NOT NULL,'private typed renderer exists');
SELECT ok((SELECT count(*)=1 FROM pg_proc WHERE oid='app_private.db03_render_admission_number(text,text,text,date,integer,bigint,bigint)'::regprocedure AND prosecdef=false AND provolatile='i'),'renderer is immutable and invoker-only');
SELECT ok(NOT has_function_privilege('authenticated','app_private.db03_render_admission_number(text,text,text,date,integer,bigint,bigint)','EXECUTE') AND NOT has_function_privilege('service_role','app_private.db03_render_admission_number(text,text,text,date,integer,bigint,bigint)','EXECUTE') AND NOT has_function_privilege('schoolos_workflow_executor','app_private.db03_render_admission_number(text,text,text,date,integer,bigint,bigint)','EXECUTE'),'no client, service or workflow formatter EXECUTE');
SELECT ok(to_regprocedure('app.render_admission_number(text,text,text,date,integer,bigint,bigint)') IS NULL AND to_regprocedure('app.approve_admission_principal(uuid,bigint,uuid,uuid)') IS NULL,'no public number formatter or APPROVE issued');
SELECT throws_ok($q$SELECT app_private.db03_render_admission_number('C','-','SESSION','2026-01-01',4,1,1)$q$,'22023','DB03 admission number render input invalid','unknown session format denied');
SELECT throws_ok($q$SELECT app_private.db03_render_admission_number(NULL,'-','FULL_YEAR','2026-01-01',4,1,1)$q$,'22023','DB03 admission number render input invalid','null prefix denied');
SELECT throws_ok($q$SELECT app_private.db03_render_admission_number('C',NULL,'FULL_YEAR','2026-01-01',4,1,1)$q$,'22023','DB03 admission number render input invalid','null separator denied');
SELECT throws_ok($q$SELECT app_private.db03_render_admission_number('C','-','FULL_YEAR',NULL,4,1,1)$q$,'22023','DB03 admission number render input invalid','null session date denied');
SELECT throws_ok($q$SELECT app_private.db03_render_admission_number('C','-','FULL_YEAR','infinity'::date,4,1,1)$q$,'22023','DB03 admission number render input invalid','infinite year denied');
SELECT throws_ok($q$SELECT app_private.db03_render_admission_number('C','-','FULL_YEAR','2026-01-01',0,1,1)$q$,'22023','DB03 admission number render input invalid','zero width denied');
SELECT throws_ok($q$SELECT app_private.db03_render_admission_number('C','-','FULL_YEAR','2026-01-01',9,1,1)$q$,'22023','DB03 admission number render input invalid','width above eight denied');
SELECT throws_ok($q$SELECT app_private.db03_render_admission_number('C','-','FULL_YEAR','2026-01-01',4,0,1)$q$,'22023','DB03 admission number render input invalid','zero starting counter denied');
SELECT throws_ok($q$SELECT app_private.db03_render_admission_number('C','-','FULL_YEAR','2026-01-01',4,10000,10000)$q$,'22023','DB03 admission number render input invalid','unrepresentable start denied');
SELECT throws_ok($q$SELECT app_private.db03_render_admission_number('C','-','FULL_YEAR','2026-01-01',4,100,99)$q$,'22023','DB03 admission number render input invalid','candidate below configured start denied');
SELECT throws_ok($q$SELECT app_private.db03_render_admission_number('C','-','FULL_YEAR','2026-01-01',4,1,0)$q$,'22023','DB03 admission number render input invalid','zero number denied');
SELECT throws_ok($q$SELECT app_private.db03_render_admission_number('C','-','FULL_YEAR','2026-01-01',4,1,10000)$q$,'22023','DB03 admission number render input invalid','number overflow denied');
SELECT throws_ok($q$SELECT app_private.db03_render_admission_number(' C','-','FULL_YEAR','2026-01-01',4,1,1)$q$,'22023','DB03 admission number render input invalid','leading whitespace in prefix denied');
SELECT throws_ok($q$SELECT app_private.db03_render_admission_number('C',' ','FULL_YEAR','2026-01-01',4,1,1)$q$,'22023','DB03 admission number render input invalid','whitespace separator denied');
SELECT throws_ok($q$SELECT app_private.db03_render_admission_number(repeat('A',81),'-','FULL_YEAR','2026-01-01',4,1,1)$q$,'22023','DB03 admission number render input invalid','prefix above 80 characters denied');
SELECT throws_ok($q$SELECT app_private.db03_render_admission_number('C',repeat('-',9),'FULL_YEAR','2026-01-01',4,1,1)$q$,'22023','DB03 admission number render input invalid','separator above eight characters denied');
SELECT throws_ok($q$SELECT app_private.db03_render_admission_number('C','-','FULL_YEAR',pg_catalog.make_date(10000,1,1),4,1,1)$q$,'22023','DB03 admission number render input invalid','five-digit calendar year denied');
SELECT * FROM finish();
ROLLBACK;
